function media_api_ids(mixed $v):array{return array_values(array_unique(array_filter(array_map('intval',(array)$v),fn($x)=>$x>0)));}
function media_api_folder(string $v):string{$v=trim(str_replace('\\','/',$v));$v=preg_replace('/[^A-Za-z0-9._\/-]+/','-',substr($v,0,180));return trim((string)$v," /.-")?:'General';}
